CustomField.formula:
IF (
AND( RecordTypeId = '01290000001IINX', /*Business & Government*/ ISPICKVAL ( Category__c , 'Corporate Airfares')), TEXT(Category__c)&' - '&TEXT( Sub_Type_Level_1__c)&' '&TEXT( Sub_Type_Level_2__c),
/*False*/ IF( AND( RecordTypeId = '01290000001IINX', /*Business & Government*/ ISPICKVAL (Category__c, 'Qantas Business Savings')),TEXT(Category__c)&' - '&TEXT( Sub_Type_Level_1__c)&' '&TEXT( Sub_Type_Level_2__c),
/*False*/ IF( RecordTypeId = '01290000001IINZ',/*SME Product*/ TEXT ( Type )&' - ' &TEXT( Sub_Type_Level_1__c)&' ' & TEXT( Sub_Type_Level_2__c),
'Others')))
